   825  inline void JSLexer::appendUnicodeToStorage(
   826      uint32_t cp,
   827      llvh::SmallVectorImpl<char> &storage) {
   828    // Sized to allow for two 16-bit values to be encoded.
   829    // A 16-bit value takes up to three bytes encoded in UTF-8.
   830    char buf[8];
   831    char *d = buf;
   832    // We need to normalize code points which would be encoded with a surrogate
   833    // pair. Note that this produces technically invalid UTF-8.
   834    if (LLVM_LIKELY(cp < 0x10000)) {
   835      hermes::encodeUTF8(d, cp);
   836    } else {
   837      assert(cp <= UNICODE_MAX_VALUE && "invalid Unicode value");
   838      cp -= 0x10000;
   839      hermes::encodeUTF8(d, UTF16_HIGH_SURROGATE + ((cp >> 10) & 0x3FF));
   840      hermes::encodeUTF8(d, UTF16_LOW_SURROGATE + (cp & 0x3FF));
   841    }
   842    storage.append(buf, d);
   843  }
